import math

# Function to compute the prime factorization of n!
def factorial_prime_factors(n):
    factors = {}
    for prime in range(2, n + 1):
        if all(prime % i for i in range(2, int(math.sqrt(prime)) + 1)):
            count = 0
            k = prime
            while k <= n:
                count += n // k
                k *= prime
            factors[prime] = count
    return factors

# Function to compute the greatest common factor of two numbers
def gcd(a, b):
    factors = {}
    common_factors = {}
    for i in range(2, min(a, b) + 1):
        if a % i == 0:
            factors[i] = 0
            while a % i == 0:
                factors[i] += 1
                a //= i
        if b % i == 0:
            factors[i] = 0
            while b % i == 0:
                factors[i] += 1
                b //= i
    for prime in factors:
        if prime in common_factors:
            common_factors[prime] = min(factors[prime], common_factors[prime])
    gcd = 1
    for prime, exp in common_factors.items():
        gcd *= prime ** exp
    return gcd

# Given numbers
num1 = math.factorial(20)
num2 = 200000

# Compute the GCF
gcf = gcd(num1, num2)

# Output the result
print(gcf)
